sandbox:
  mode: docker
  image: ghcr.io/openclaw/clawscan-runtime:latest
  env: [OPENAI_API_KEY]
  mounts:
    - /opt/rules
    - path: /var/cache/clawscan
      write: true
profiles:
  review:
    scanners:
      - skillspector
      - id: clawscan-static
