            equals: critical
            aciton: block
`,
		"invalid action": `
          - id: risky
            path: result.risk
            equals: critical
            action: deny
`,
		"false exists": `
          - id: risky
            path: result.risk
            exists: false
            action: block
`,
		"both conditions": `
          - id: risky
            path: result.risk
            equals: critical
            exists: true
            action: block
`,
		"numeric normalization": `
          - id: risky
            path: result.score
            equals: 10
            normalize: identifier
            action: block
`,
		"empty path list": `
          - id: risky
            path: []
            exists: true
            action: block
`,
		"indexed scalar path": `
          - id: risky
            path: "findings[0].severity"
            equals: critical
            action: block
`,
		"indexed path in list": `
          - id: risky
            path: [result.risk, "findings[0].severity"]
