			}
			if existing {
				if err := os.WriteFile(output, []byte("private previous result"), 0o600); err != nil {
					t.Fatal(err)
				}
			}
			artifact, err := Run(Options{Target: target, Scanners: []string{"clawscan-static"}, OutputPath: output}, RunContext{Env: map[string]string{}})
