func TestDockerSandboxLabelsForWorkerCleanup(t *testing.T) {
	for _, runID := range []string{"", "worker-123", "invalid id", strings.Repeat("a", 65)} {
		t.Run(runID, func(t *testing.T) {
			host := &recordingCommandRunner{stdout: `{}`}
			commandRunner, _, err := commandRunnerForOptions(Options{}, RunContext{HostCommandRunner: host}, map[string]string{SandboxRunIDEnv: runID})
			if err != nil {
				t.Fatal(err)
			}
			var previousCommandID string
			for range 2 {
				_, err := commandRunner.Run("scanner", nil, "", 0)
				if strings.Contains(runID, " ") || len(runID) > 64 {
					if err == nil || len(host.calls) != 0 {
						t.Fatalf("invalid ID executed Docker: calls=%v err=%v", host.calls, err)
					}
					return
				}
				if err != nil {
					t.Fatal(err)
				}
				args := host.calls[len(host.calls)-1].args
				if runID == "" {
					if containsArg(args, "--label") {
						t.Fatalf("unsupervised run has worker labels: %v", args)
					}
					continue
				}
				if !containsArgPair(args, "--label", SandboxRunIDLabel+"="+runID) || containsArgPair(args, "-e", SandboxRunIDEnv) {
					t.Fatalf("worker ID must be a label, not container environment: %v", args)
				}
				var commandID string
				for i, arg := range args[:len(args)-1] {
					if arg == "--label" && strings.HasPrefix(args[i+1], SandboxCommandIDLabel+"=") {
						commandID = strings.TrimPrefix(args[i+1], SandboxCommandIDLabel+"=")
					}
				}
				if commandID == previousCommandID || !sandboxRunIDPattern.MatchString(commandID) {
					t.Fatalf("command ID %q must be valid and unique", commandID)
				}
				previousCommandID = commandID
			}
		})
	}
}

package main

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"
)

type benchmarkArtifact struct {
	Benchmark benchmarkMetadata `json:"benchmark"`
	Summary   benchmarkSummary  `json:"summary"`
}

type benchmarkMetadata struct {
	ID     string `json:"id"`
	Split  string `json:"split"`
	Offset int    `json:"offset"`
	Limit  int    `json:"limit"`
	Rows   int    `json:"rows"`
}

type benchmarkSummary struct {
	CaseCount  int                        `json:"caseCount"`
	Evaluation benchmarkEvaluationSummary `json:"evaluation"`
}

type benchmarkEvaluationSummary struct {
	Scored     int     `json:"scored"`
	Correct    int     `json:"correct"`
	Incorrect  int     `json:"incorrect"`
	Abstained  int     `json:"abstained"`
	Unscorable int     `json:"unscorable"`
	Errors     int     `json:"errors"`
	Accuracy   float64 `json:"accuracy"`
}

type benchmarkBlockOptions struct {
	Profile     string
	Artifact    string
	WorkflowURL string
	Commit      string
}

func main() {
	if err := run(os.Args[1:], os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
}

func run(args []string, stdout io.Writer) error {
	flags := flag.NewFlagSet("update-benchmark-readme", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	artifactPath := flags.String("artifact", "", "benchmark artifact JSON path")
	readmePath := flags.String("readme", "README.md", "README path")
	profile := flags.String("profile", "clawhub", "profile marker id")
	workflowURL := flags.String("workflow-url", "", "workflow run URL")
	commit := flags.String("commit", "", "commit SHA or ref")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *artifactPath == "" {
		return errors.New("missing required --artifact")
	}
	if *profile == "" {
		return errors.New("missing required --profile")
	}

	artifact, err := readBenchmarkArtifact(*artifactPath)
	if err != nil {
		return err
	}
	readme, err := os.ReadFile(*readmePath)
	if err != nil {
		return fmt.Errorf("read README %s: %w", *readmePath, err)
	}
	block := renderBenchmarkBlock(artifact, benchmarkBlockOptions{
		Profile:     *profile,
		Artifact:    *artifactPath,
		WorkflowURL: *workflowURL,
		Commit:      *commit,
	})
	updated, err := updateReadmeBenchmarkBlock(string(readme), *profile, block)
	if err != nil {
		return err
	}
	if err := os.WriteFile(*readmePath, []byte(updated), 0o644); err != nil {
		return fmt.Errorf("write README %s: %w", *readmePath, err)
	}
	fmt.Fprint(stdout, block)
	return nil
}

func readBenchmarkArtifact(path string) (benchmarkArtifact, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return benchmarkArtifact{}, fmt.Errorf("read benchmark artifact %s: %w", path, err)
	}
	var artifact benchmarkArtifact
	if err := json.Unmarshal(data, &artifact); err != nil {
		return benchmarkArtifact{}, fmt.Errorf("parse benchmark artifact %s: %w", path, err)
	}
	if artifact.Benchmark.ID == "" {
		return benchmarkArtifact{}, fmt.Errorf("benchmark artifact %s missing benchmark.id", path)
	}
	return artifact, nil
}

func renderBenchmarkBlock(artifact benchmarkArtifact, opts benchmarkBlockOptions) string {
	caseCount := artifact.Summary.CaseCount
	if caseCount == 0 {
		caseCount = artifact.Benchmark.Rows
	}
	lines := []string{
		benchmarkStartMarker(opts.Profile),
		fmt.Sprintf("Profile: `%s`", opts.Profile),
		fmt.Sprintf("Benchmark: `%s` (`%s` split)", artifact.Benchmark.ID, artifact.Benchmark.Split),
		fmt.Sprintf("Cases: `%d`", caseCount),
		fmt.Sprintf("Accuracy: `%.4f`", artifact.Summary.Evaluation.Accuracy),
		fmt.Sprintf(
			"Scored: `%d`, correct: `%d`, incorrect: `%d`, abstained: `%d`, unscorable: `%d`, errors: `%d`",
			artifact.Summary.Evaluation.Scored,
			artifact.Summary.Evaluation.Correct,
			artifact.Summary.Evaluation.Incorrect,
			artifact.Summary.Evaluation.Abstained,
			artifact.Summary.Evaluation.Unscorable,
			artifact.Summary.Evaluation.Errors,
		),
	}
	if opts.Artifact != "" {
		lines = append(lines, fmt.Sprintf("Artifact: `%s`", opts.Artifact))
	}
	if opts.WorkflowURL != "" {
		lines = append(lines, "Workflow run: "+opts.WorkflowURL)
	}
	if opts.Commit != "" {
		lines = append(lines, fmt.Sprintf("Commit: `%s`", opts.Commit))
	}
	lines = append(lines, benchmarkEndMarker(opts.Profile), "")
	return strings.Join(lines, "\n")
}

func updateReadmeBenchmarkBlock(readme string, profile string, replacement string) (string, error) {
	start := benchmarkStartMarker(profile)
	end := benchmarkEndMarker(profile)
	startIndex := strings.Index(readme, start)
	endIndex := strings.Index(readme, end)
	if startIndex == -1 || endIndex == -1 || endIndex < startIndex {
		return "", fmt.Errorf("missing benchmark marker pair for profile %s", profile)
	}
	endIndex += len(end)
	if strings.HasPrefix(readme[endIndex:], "\r\n") {
		endIndex += 2
	} else if strings.HasPrefix(readme[endIndex:], "\n") {
		endIndex++
	}

	if !strings.Contains(replacement, start) || !strings.Contains(replacement, end) {
		replacement = start + "\n" + strings.Trim(replacement, "\n") + "\n" + end
	}
	if !strings.HasSuffix(replacement, "\n") {
		replacement += "\n"
	}
	return readme[:startIndex] + replacement + readme[endIndex:], nil
}

func benchmarkStartMarker(profile string) string {
	return fmt.Sprintf("<!-- clawscan-benchmark:%s:start -->", profile)
}

func benchmarkEndMarker(profile string) string {
	return fmt.Sprintf("<!-- clawscan-benchmark:%s:end -->", profile)
}

import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { test } from "node:test";

const binary = resolve(process.env.CLAWSCAN_BIN || "./clawscan");

for (const name of ["plain", 'My Skill, "v2"']) {
  test(`Docker preserves paths and mount permissions: ${name}`, { timeout: 120_000 }, () => {
    const root = mkdtempSync(join(tmpdir(), "clawscan-docker-mounts-"));
    try {
      const target = join(root, name);
      const rules = join(root, `${name} rules`);
      const cache = join(root, `${name} cache`);
      for (const path of [target, rules, cache]) mkdirSync(path);
      writeFileSync(join(target, "SKILL.md"), "# Synthetic mount fixture\n");
      writeFileSync(join(rules, "rule.txt"), "synthetic rule\n");
      writeFileSync(join(target, "probe.sh"), `set -eu
test "$(cat "$1/SKILL.md")" = "# Synthetic mount fixture"
test "$(cat "$PROOF_RULES/rule.txt")" = "synthetic rule"
if (printf changed > "$1/SKILL.md") 2>/dev/null; then
  echo "target unexpectedly writable" >&2
  exit 1
fi
if (touch "$PROOF_RULES/unexpected") 2>/dev/null; then
  echo "rules unexpectedly writable" >&2
  exit 1
fi
printf 'container wrote cache\n' > "$PROOF_CACHE/proof.txt"
printf '{"targetReadOnly":true,"rulesReadOnly":true,"cacheWritable":true}\n'
`);
      const config = join(root, "config.json");
      writeFileSync(config, JSON.stringify({
        version: 1,
        profiles: {
          proof: {
            scanners: [{
              id: "mount-proof",
              command: "sh {{target}}/probe.sh {{target}}",
              env: ["PROOF_RULES", "PROOF_CACHE"],
              targets: ["skill"],
            }],
            sandbox: {
              image: "alpine:3.23",
              mounts: [rules, { path: cache, write: true }],
            },
          },
        },
      }));
      const stdout = execFileSync(binary, [target, "--config", config, "--profile", "proof", "--sandbox", "docker", "--json"], {
        encoding: "utf8",
        timeout: 110_000,
        env: { ...process.env, PROOF_RULES: rules, PROOF_CACHE: cache },
      });
      const artifact = JSON.parse(stdout);
      const scanner = artifact.scanners["mount-proof"];
      assert.equal(scanner.status, "completed", JSON.stringify(scanner));
      assert.deepEqual(scanner.raw, { targetReadOnly: true, rulesReadOnly: true, cacheWritable: true });
      assert.equal(readFileSync(join(target, "SKILL.md"), "utf8"), "# Synthetic mount fixture\n");
      assert.equal(readFileSync(join(cache, "proof.txt"), "utf8"), "container wrote cache\n");
    } finally {
      rmSync(root, { recursive: true, force: true });
    }
  });
}

